tool_input.command:
cat > /tmp/test_weekly.js << 'EOF'
import { monthlyCents } from './src/cycles.js';

// Test weekly calculation: €59.90 per week = €259.57 per month
const weeklyPlan = { price: 5990, cycle: 'weekly' };
const monthly = monthlyCents(weeklyPlan);
console.log(`€59.90/week = €${(monthly/100).toFixed(2)}/month`);
console.log(`Calculated: ${monthly} cents`);
console.log(`Expected: 25957 cents (€259.57)`);
console.log(`Match: ${monthly === 25957}`);

// Test €12/week = €52/month
const weeklyPlan2 = { price: 1200, cycle: 'weekly' };
const monthly2 = monthlyCents(weeklyPlan2);
console.log(`\n€12.00/week = €${(monthly2/100).toFixed(2)}/month`);
console.log(`Calculated: ${monthly2} cents`);
console.log(`Expected: 5200 cents (€52.00)`);
console.log(`Match: ${monthly2 === 5200}`);
EOF
node /tmp/test_weekly.js
